Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -28,4 +28,36 @@
 </main>
 <footer class="bottom-bar"><span>STAY ALIVE. STAY INVENTIVE.</span><div class="bottom-controls"><span><i class="key">W</i><i class="key">A</i><i class="key">S</i><i class="key">D</i> MOVE</span><span><i class="key">ENTER</i> CREATE</span></div></footer>
 </div>
 <script>
+(() => {
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage');
+const $=id=>document.getElementById(id);let W=0,H=0,dpr=1,last=0,elapsed=0,spawnTimer=0,attackTimer=0,shake=0,started=false,ended=false,won=false,essence=3,score=0,day=1,keys={},mouse={x:0,y:0};
+const player={x:0,y:0,r:12,hp:100,speed:178,invuln:0,shield:0,blade:0,bow:0};let enemies=[],objects=[],particles=[],projectiles=[],fires=[],texts=[];
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function resize(){const r=stage.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W/2;player.y=H/2}draw()}
+window.addEventListener('resize',resize);resize();
+function log(message,type=''){const el=document.createElement('div');el.className='log-entry '+type;el.innerHTML=`<time>${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${message}</span>`;$('log').prepend(el);while($('log').children.length>6)$('log').lastChild.remove()}
+function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1550)}
+function updateUI(){ $('hp').textContent=Math.ceil(player.hp);$('healthBar').style.width=player.hp+'%';$('essence').textContent=String(essence).padStart(2,'0');$('energy').textContent=String(essence).padStart(2,'0');$('score').textContent=String(score).padStart(4,'0');const sec=Math.floor(elapsed);$('clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');day=Math.floor(sec/35)+1;$('day').textContent=String(day).padStart(2,'0');$('threat').textContent=sec<25?'LOW':sec<70?'RISING':'CRITICAL';$('threat').style.color=sec<25?'#c8f169':sec<70?'#ffbf68':'#ff655b'}
+function start(){if(started)return;started=true;$('overlay').style.display='none';player.x=W/2;player.y=H/2;log('You woke up somewhere new. <b>Good luck.</b>','good');$('wish').focus()}
+$('startBtn').addEventListener('click',start);
+function spawnEnemy(){const side=Math.floor(rand(0,4));let x=side===0?rand(0,W):side===1?W+20:side===2?rand(0,W):-20,y=side===0?-20:side===1?rand(0,H):side===2?H+20:rand(0,H);const fast=Math.random()<Math.min(.15+elapsed/300,.48);enemies.push({x,y,r:fast?9:12,hp:fast?2:3,speed:(fast?rand(65,85):rand(34,54))+Math.min(elapsed*.12,24),hit:0,fast})}
+function addText(x,y,text,color='#c8f169'){texts.push({x,y,text,color,life:1})}
+function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(30,145);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.25,.65),max:.65,color,size:rand(2,4)})}}
+function draw(){if(!W||!H)return;ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake*=.84;if(shake<.2)shake=0}ctx.clearRect(-12,-12,W+24,H+24);
+ctx.fillStyle='#19271c';ctx.fillRect(0,0,W,H);
+const grid=38,ox=(elapsed*3)%grid,oy=(elapsed*1.6)%grid;ctx.strokeStyle='#a5bd8a0b';ctx.lineWidth=1;for(let x=-grid+ox;x<W+grid;x+=grid){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=-grid+oy;y<H+grid;y+=grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
+// Soft pools of ambient light
+const glow=ctx.createRadialGradient(W*.5,H*.48,20,W*.5,H*.48,Math.max(W,H)*.65);glow.addColorStop(0,'#52724415');glow.addColorStop(1,'#080e0b66');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
+// Procedural grass flecks
+for(let i=0;i<95;i++){let x=(i*173.7+Math.sin(i*81.3)*100+W*2)%W,y=(i*97.3+Math.cos(i*17.8)*50+H*2)%H;ctx.fillStyle=i%3?'#a6ba7b13':'#d0d49310';ctx.fillRect(x,y,2,2)}
+for(const o of objects){ctx.save();ctx.translate(o.x,o.y);if(o.kind==='wall'){ctx.fillStyle='#79866a';ctx.strokeStyle='#b8c5a6';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(-20,-8,40,16,3);ctx.fill();ctx.stroke();ctx.fillStyle='#4c5946';ctx.fillRect(-12,-5,9,3);ctx.fillRect(4,1,11,3)}else if(o.kind==='tree'){ctx.fillStyle='#5e4630';ctx.fillRect(-4,0,8,15);ctx.fillStyle='#496d43';ctx.beginPath();ctx.arc(0,-4,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#729253';ctx.beginPath();ctx.arc(-5,-9,10,0,Math.PI*2);ctx.fill()}else if(o.kind==='crystal'){ctx.fillStyle='#8bd8d2';ctx.shadowColor='#8bd8d2';ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(0,-13);ctx.lineTo(9,0);ctx.lineTo(0,13);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.shadowBlur=0}ctx.restore()}
+for(const f of fires){ctx.beginPath();ctx.fillStyle=`rgba(255,123,54,${.16+.09*Math.sin(elapsed*14+f.x)})`;ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffae4d70';ctx.beginPath();ctx.arc(f.x,f.y,f.r*.72,0,Math.PI*2);ctx.stroke()}
+for(const p of projectiles){ctx.fillStyle='#d9f792';ctx.shadowColor='#c8f169';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}
+for(const e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.fillStyle=e.hit>0?'#f4af78':e.fast?'#c57362':'#86946c';ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.fast?'#653f3c':'#3e5138';ctx.beginPath();ctx.arc(-e.r*.35,-2,2,0,Math.PI*2);ctx.arc(e.r*.35,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#455343';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,e.r+3,-2.3,-.8);ctx.stroke();ctx.restore()}
+// player aura & avatar
+ctx.beginPath();ctx.fillStyle=player.shield>0?'#8bd8d22a':'#c8f16912';ctx.arc(player.x,player.y,player.shield>0?25:20,0,Math.PI*2);ctx.fill();if(player.shield>0){ctx.strokeStyle='#8bd8d2cc';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y,22+Math.sin(elapsed*8)*2,0,Math.PI*2);ctx.stroke()}
+ctx.save();ctx.translate(player.x,player.y);ctx.rotate(Math.sin(elapsed*7)*.035);ctx.fillStyle=player.invuln>0&&Math.floor(elapsed*18)%2?'#ffffff': '#d9e7c7';ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#354a37';ctx.beginPath();ctx.arc(3,-2,2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c8f169';ctx.beginPath();ctx.arc(-7,6,3,0,Math.PI*2);ctx.fill();ctx.restore();
+for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;
+for(const t of texts){ctx.globalAlpha=clamp(t.life*2,0,1);ctx.fillStyle=t.color;ctx.font='11px "DM Mono", monospace';ctx.textAlign='center';ctx.fillText(t.text,t.x,t.y)}ctx.globalAlpha=1;
+if(!started){ctx.strokeStyle='#c8f16924';ctx.setLineDash([3,8]);ctx.beginPath();ctx.arc(W/2,H/2,104,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}

input.newString:
if(!started){ctx.strokeStyle='#c8f16924';ctx.setLineDash([3,8]);ctx.beginPath();ctx.arc(W/2,H/2,104,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}
function makeThing(raw){const word=raw.trim().toLowerCase();if(!word||!started||ended)return;if(essence<1){toast('NOT ENOUGH ESSENCE — defeat a creature');log('Not enough essence to make that.','bad');return}essence--;const x=player.x,y=player.y;let name='';
if(/food|apple|berry|meal|bread|soup|snack|pizza|cake|fruit|meat|heal|medicine|potion/.test(word)){player.hp=Math.min(100,player.hp+32);name='wild provisions';addText(x,y-22,'+32 VITALS','#ff8d74');}
else if(/fire|flame|burn|torch|lava|sun|lightning|bomb|explode|dragon/.test(word)){fires.push({x,y,r:92,life:5,max:5,power:4});name='ember storm';burst(x,y,'#ff9948',22)}
else if(/sword|blade|knife|spear|axe|katana|weapon|claw|hammer/.test(word)){player.blade=Math.min(3,player.blade+1);name=player.blade===1?'thornblade':`thornblade +${player.blade}`;burst(x,y,'#d7e99d',9)}
else if(/bow|arrow|gun|rifle|crossbow|wand|staff|slingshot/.test(word)){player.bow=Math.min(3,player.bow+1);name='wildwood bow';burst(x,y,'#a2d8be',9)}
else if(/shield|armor|armour|helmet|bubble|forcefield|guard/.test(word)){player.shield=Math.max(player.shield,12);name='barkskin shield';burst(x,y,'#8bd8d2',12)}
else if(/wall|fence|door|fort|rock|barricade|house|castle/.test(word)){let near=objects.filter(o=>dist(o,player)<35);if(near.length){name='stone already stands'}else{objects.push({kind:'wall',x:x+rand(-43,43),y:y+rand(-43,43)});name='mossstone wall'}burst(x,y,'#b7c09a',8)}
else if(/tree|forest|plant|flower|wood|bush|garden|vine/.test(word)){objects.push({kind:'tree',x:x+rand(-55,55),y:y+rand(-55,55)});name='old-growth tree';burst(x,y,'#a9cb72',8)}
else if(/friend|dog|cat|wolf|bear|robot|golem|ghost|fairy|bird|companion|ally|turtle/.test(word)){objects.push({kind:'ally',x:x+rand(-80,80),y:y+rand(-80,80),life:20});name='new friend';burst(x,y,'#e1cc91',12)}
else if(/star|crystal|gem|diamond|moon|spark|magic|essence|coin/.test(word)){objects.push({kind:'crystal',x:x+rand(-75,75),y:y+rand(-75,75),life:18});name='glimmering crystal';burst(x,y,'#8bd8d2',12)}
else {const options=['sword','fire','food','shield','bow','wall','tree','friend','crystal'];const h=[...word].reduce((a,c)=>((a*31+c.charCodeAt(0))|0),7);const pick=options[Math.abs(h)%options.length];if(pick==='sword'){player.blade=Math.min(3,player.blade+1);name='wild-forged sword'}else if(pick==='fire'){fires.push({x,y,r:85,life:4,max:4,power:3});name='pocket wildfire'}else if(pick==='food'){player.hp=Math.min(100,player.hp+26);name='something delicious';addText(x,y-22,'+26 VITALS','#ff8d74')}else if(pick==='shield'){player.shield=Math.max(player.shield,10);name='portable safe place'}else if(pick==='bow'){player.bow=Math.min(3,player.bow+1);name='self-aiming bow'}else if(pick==='wall'){objects.push({kind:'wall',x:x+rand(-40,40),y:y+rand(-40,40)});name='a very useful wall'}else if(pick==='tree'){objects.push({kind:'tree',x:x+rand(-40,40),y:y+rand(-40,40)});name='convenient tree'}else if(pick==='friend'){objects.push({kind:'ally',x:x+rand(-80,80),y:y+rand(-80,80),life:20});name='mysterious companion'}else{objects.push({kind:'crystal',x:x+rand(-70,70),y:y+rand(-70,70),life:18});name='strange little crystal'}burst(x,y,'#c8f169',10)}
addText(x,y-25,'✦ '+name);toast('MADE: '+name.toUpperCase());log(`You made <b>${name}</b> from “${escapeHTML(raw)}”.`,'good');updateUI();$('wish').value='';$('wish').blur()}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('craftForm').addEventListener('submit',e=>{e.preventDefault();makeThing($('wish').value)});document.querySelectorAll('.recipe').forEach(b=>b.addEventListener('click',()=>makeThing(b.dataset.word)));

