canvas.addEventListener('pointerdown',()=>{if(document.activeElement===$('wish'))$('wish').blur()});
updateUI();requestAnimationFrame(function loop(now){const dt=Math.min((now-last)/1000||0,.04);last=now;update(dt);draw();requestAnimationFrame(loop)});
